using System.Globalization;
using System.Text;
using System.Text.Json;

namespace Mmorpg.Tools.ProtocolGenerator;

// The lock file records the wire fingerprint of every protocol version. A version keeps its
// fingerprint forever, so a changed wire contract fails generation until protocol.version
// grows, and no version number is ever reused for another contract.
public static class ProtocolVersionLock
{
    private const string Description =
        "Generated by tools/ProtocolGenerator. The SHA-256 fingerprint of the wire contract of every protocol version. "
        + "A changed contract needs a higher protocol.version in realtime-protocol.json.";

    // Returns the lock content with the given version recorded, or throws when the version
    // already has another fingerprint or lies below the newest locked version.
    public static string Update(string? existingContent, ushort version, string fingerprint)
    {
        ArgumentNullException.ThrowIfNull(fingerprint);
        var versions = existingContent is null ? new SortedDictionary<int, string>() : Parse(existingContent);
        if (versions.TryGetValue(version, out var locked))
        {
            if (!string.Equals(locked, fingerprint, StringComparison.Ordinal))
            {
                throw new InvalidDataException(
                    $"The wire contract of protocol version {version} changed: it now has fingerprint {fingerprint}, "
                    + $"but the lock records {locked}. Increase protocol.version in the schema.");
            }
        }
        else
        {
            var newest = versions.Count == 0 ? 0 : versions.Keys.Max();
            if (version < newest)
            {
                throw new InvalidDataException(
                    $"Protocol version {version} is below the newest locked version {newest}; versions only grow.");
            }

            versions[version] = fingerprint;
        }

        return Format(versions);
    }

    public static SortedDictionary<int, string> Parse(string content)
    {
        try
        {
            using var document = JsonDocument.Parse(content);
            var root = SchemaNode.Object(document.RootElement, "$");
            root.Ignore("description");
            var versions = new SortedDictionary<int, string>();
            foreach (var entry in root.RequiredObjects("versions"))
            {
                var version = entry.RequiredInteger("version");
                var fingerprint = entry.RequiredString("fingerprint");
                if (version is < 1 or > ushort.MaxValue)
                {
                    throw entry.Error("version", "must be between 1 and 65535.");
                }

                if (fingerprint.Length != 64 || !fingerprint.All(char.IsAsciiHexDigitLower))
                {
                    throw entry.Error("fingerprint", "must be 64 lowercase hexadecimal characters.");
                }

                if (!versions.TryAdd((int)version, fingerprint))
                {
                    throw entry.Error("version", $"{version} appears more than once.");
                }

                entry.EnsureFullyRead();
            }

            root.EnsureFullyRead();
            return versions;
        }
        catch (Exception exception) when (exception is JsonException or ProtocolSchemaException)
        {
            throw new InvalidDataException($"The protocol version lock is invalid: {exception.Message}", exception);
        }
    }

    private static string Format(SortedDictionary<int, string> versions)
    {
        var text = new StringBuilder();
        text.Append("{\n");
        text.Append("  \"description\": ").Append(JsonSerializer.Serialize(Description)).Append(",\n");
        text.Append("  \"versions\": [\n");
        text.Append(string.Join(",\n", versions.Select(entry => string.Create(
            CultureInfo.InvariantCulture,
            $"    {{ \"version\": {entry.Key}, \"fingerprint\": \"{entry.Value}\" }}"))));
        text.Append("\n  ]\n}\n");
        return text.ToString();
    }
}
